package com.lynn.s34598901.medtrack.data.symptoms

import androidx.room.Entity
import androidx.room.ForeignKey
import androidx.room.Index
import androidx.room.PrimaryKey
import com.lynn.s34598901.medtrack.data.patients.Patient

/**
 * Represents one symptom record saved for a patient
 */
@Entity(tableName = "symptoms",
    foreignKeys = [ForeignKey(entity = Patient :: class, parentColumns = ["patientID"], childColumns = ["patientID"], onDelete = ForeignKey.CASCADE)], indices = [Index(
        "patientID")])
data class Symptom(

    // Unique symptom record ID generated by Room
    @PrimaryKey(autoGenerate = true)
    val symptomId: Int = 0,

    // Patient ID linked to the patient who logged this symptom
    val patientID: String,

    // Symptom category
    val category: String,

    // Severity rating
    val severity: Int,

    // Optional notes entered by patient
    val notes: String,

    // Date and time when the symptom occurred
    val dateTime: String
)
